// Strategy interface: how a log record becomes an output string.
interface LogFormatter {
    String format(LogRecord record); // renders the record into a single output string
}

// Renders a record as a bracketed level, logger name, and message.
class PlainTextLogFormatter implements LogFormatter {
    @Override
    public String format(LogRecord record) {
        return "[" + record.getLevel() + "] " + record.getLoggerName() + ": " + record.getMessage(); // simple readable line
    }
}

// Renders a record as a single line JSON object.
class JsonLogFormatter implements LogFormatter {
    @Override
    public String format(LogRecord record) {
        return "{\"level\":\"" + record.getLevel() + "\",\"logger\":\"" + record.getLoggerName() + "\",\"message\":\"" + record.getMessage() + "\"}"; // machine readable line
    }
}

// Observer interface: one output destination for log records.
interface LogAppender {
    void onLog(LogRecord record); // decides independently whether and how to write this record
}

// Writes matching records to the console, using its own threshold and formatter.
class ConsoleLogAppender implements LogAppender {
    private final LogLevel minLevel;      // this appender's own threshold
    private final LogFormatter formatter;   // this appender's own formatting strategy

    public ConsoleLogAppender(LogLevel minLevel, LogFormatter formatter) {
        this.minLevel = minLevel;     // store threshold
        this.formatter = formatter;     // store formatter
    }

    @Override
    public void onLog(LogRecord record) {
        if (record.getLevel().getRank() < minLevel.getRank()) return; // below this appender's own threshold, ignore
        System.out.println(formatter.format(record)); // format and print
    }
}

// Simulates writing matching records to a file by accumulating formatted lines in memory.
class FileLogAppender implements LogAppender {
    private final LogLevel minLevel;                                     // this appender's own threshold
    private final LogFormatter formatter;                                  // this appender's own formatting strategy
    private final java.util.List<String> capturedLines = new java.util.ArrayList<>(); // simulated file contents

    public FileLogAppender(LogLevel minLevel, LogFormatter formatter) {
        this.minLevel = minLevel;     // store threshold
        this.formatter = formatter;     // store formatter
    }

    @Override
    public void onLog(LogRecord record) {
        if (record.getLevel().getRank() < minLevel.getRank()) return; // below this appender's own threshold, ignore
        capturedLines.add(formatter.format(record)); // format and append to the simulated file
    }

    public java.util.List<String> getCapturedLines() { return capturedLines; } // exposes the simulated file's final contents
}

