// Reusable level name lookup, since C++ enum class has no built in name() like Java or Python.
string levelName(LogLevel level) {
    if (level == LogLevel::DEBUG) return "DEBUG";     // DEBUG name
    if (level == LogLevel::INFO) return "INFO";          // INFO name
    if (level == LogLevel::WARN) return "WARN";             // WARN name
    return "ERROR";                                            // ERROR name
}

// Strategy interface: how a log record becomes an output string.
class LogFormatter {
public:
    virtual string format(const LogRecord& record) = 0;
    virtual ~LogFormatter() {}
};

// Renders a record as a bracketed level, logger name, and message.
class PlainTextLogFormatter : public LogFormatter {
public:
    string format(const LogRecord& record) override {
        return "[" + levelName(record.level) + "] " + record.loggerName + ": " + record.message; // simple readable line
    }
};

// Renders a record as a single line JSON object.
class JsonLogFormatter : public LogFormatter {
public:
    string format(const LogRecord& record) override {
        return "{\"level\":\"" + levelName(record.level) + "\",\"logger\":\"" + record.loggerName + "\",\"message\":\"" + record.message + "\"}"; // machine readable line
    }
};

// Observer interface: one output destination for log records.
class LogAppender {
public:
    virtual void onLog(const LogRecord& record) = 0;
    virtual ~LogAppender() {}
};

// Writes matching records to the console, using its own threshold and formatter.
class ConsoleLogAppender : public LogAppender {
    LogLevel minLevel;                    // this appender's own threshold
    shared_ptr<LogFormatter> formatter;      // this appender's own formatting strategy

public:
    ConsoleLogAppender(LogLevel level, shared_ptr<LogFormatter> fmt) : minLevel(level), formatter(fmt) {} // store threshold and formatter

