// A named source of log events, gating calls against its own threshold before notifying appenders.
class Logger {
    private final String name;                                              // this logger's name
    private LogLevel minLevel;                                                 // this logger's own threshold
    private final java.util.List<LogAppender> appenders = new java.util.ArrayList<>(); // registered destinations
    private int sequenceCounter = 0;                                                // running sequence number

    public Logger(String name, LogLevel minLevel) {
        this.name = name;         // store name
        this.minLevel = minLevel;   // store threshold
    }

    public String getName() { return name; } // name getter

    // Registers a new appender, rejecting an already-registered instance.
    public void addAppender(LogAppender appender) {
        if (appenders.contains(appender)) { // this exact instance is already registered
            throw new DuplicateAppenderException("Appender is already registered on logger " + name);
        }
        appenders.add(appender); // register it
    }

    // Unregisters an appender, rejecting one that was never added.
    public void removeAppender(LogAppender appender) {
        if (!appenders.remove(appender)) { // remove returns false if it was never present
            throw new AppenderNotRegisteredException("Appender is not registered on logger " + name);
        }
    }

    // Gates the call against this logger's own threshold, then notifies every appender.
    public void log(LogLevel level, String message) {
        if (level.getRank() < minLevel.getRank()) return; // below this logger's own threshold, drop entirely
        sequenceCounter++;                                    // bump the sequence counter
        LogRecord record = new LogRecord(sequenceCounter, name, level, message); // build the record
        for (LogAppender appender : appenders) appender.onLog(record);             // notify every registered appender
    }
}

// Creates and caches Logger instances by name, guaranteeing the same name always returns the same instance.
class LoggerFactory {
    private final java.util.Map<String, Logger> cache = new java.util.HashMap<>(); // name -> Logger

    // Returns the cached logger for this name, creating and caching one on first use.
    public synchronized Logger getLogger(String name) {
        if (name == null || name.trim().isEmpty()) { // blank names are not allowed
            throw new InvalidLoggerNameException("Logger name must not be blank");
        }
        if (cache.containsKey(name)) return cache.get(name); // already cached, return the same instance
        Logger logger = new Logger(name, LogLevel.INFO);        // default threshold is INFO
        cache.put(name, logger);                                  // cache it for future lookups
        return logger; // hand back the newly created logger
    }
}

