#include <string>
#include <vector>
#include <map>
#include <memory>
#include <algorithm>
using namespace std;

// A named source of log events, gating calls against its own threshold before notifying appenders.
class Logger {
    string name;                               // this logger's name
    LogLevel minLevel;                            // this logger's own threshold
    vector<shared_ptr<LogAppender>> appenders;       // registered destinations
    int sequenceCounter = 0;                            // running sequence number

public:
    Logger() : minLevel(LogLevel::INFO) {}
    Logger(string n, LogLevel level) : name(n), minLevel(level) {} // constructor stores name and threshold

    string getName() { return name; } // name getter

    void addAppender(shared_ptr<LogAppender> appender) {
        for (auto& existing : appenders) {                                     // scan every already-registered appender
            if (existing == appender) throw DuplicateAppenderException("Appender is already registered on logger " + name); // same instance found
        }
        appenders.push_back(appender); // register it
    }

    void removeAppender(shared_ptr<LogAppender> appender) {
        auto it = find(appenders.begin(), appenders.end(), appender); // look for this exact instance
        if (it == appenders.end()) throw AppenderNotRegisteredException("Appender is not registered on logger " + name); // it was never present
        appenders.erase(it); // unregister it
    }

    void log(LogLevel level, string message) {
        if ((int)level < (int)minLevel) return;                     // below this logger's own threshold, drop entirely
        sequenceCounter++;                                              // bump the sequence counter
        LogRecord record(sequenceCounter, name, level, message);          // build the record
        for (auto& appender : appenders) appender->onLog(record);            // notify every registered appender
    }
};

// Creates and caches Logger instances by name, guaranteeing the same name always returns the same instance.
class LoggerFactory {
    map<string, shared_ptr<Logger>> cache; // name -> Logger

public:
    shared_ptr<Logger> getLogger(string name) {
        if (name.empty()) throw InvalidLoggerNameException("Logger name must not be blank"); // blank names are not allowed
        if (cache.find(name) != cache.end()) return cache.at(name);   // already cached, return the same instance
        auto logger = make_shared<Logger>(name, LogLevel::INFO);         // default threshold is INFO
        cache[name] = logger;                                               // cache it for future lookups
        return logger; // hand back the newly created logger
    }
};

