import java.util.*;

public class Main {
    public static void main(String[] args) {
        LoggerFactory factory = new LoggerFactory();

        Logger logger1 = factory.getLogger("com.app.Service");
        Logger logger2 = factory.getLogger("com.app.Service");
        System.out.println("Same instance: " + (logger1 == logger2));

        ConsoleLogAppender consoleAppender = new ConsoleLogAppender(LogLevel.WARN, new PlainTextLogFormatter());
        FileLogAppender fileAppender = new FileLogAppender(LogLevel.DEBUG, new JsonLogFormatter());
        logger1.addAppender(consoleAppender);
        logger1.addAppender(fileAppender);

        logger1.log(LogLevel.DEBUG, "starting up");
        logger1.log(LogLevel.INFO, "service started");
        logger1.log(LogLevel.ERROR, "something failed");

        try {
            logger1.addAppender(consoleAppender);
        } catch (DuplicateAppenderException e) {
            System.out.println("Caught expected: " + e.getMessage());
        }

        LogAppender neverAdded = new ConsoleLogAppender(LogLevel.ERROR, new PlainTextLogFormatter());
        try {
            logger1.removeAppender(neverAdded);
        } catch (AppenderNotRegisteredException e) {
            System.out.println("Caught expected: " + e.getMessage());
        }

        try {
            factory.getLogger("");
        } catch (InvalidLoggerNameException e) {
            System.out.println("Caught expected: " + e.getMessage());
        }

        System.out.println("Captured file lines: " + fileAppender.getCapturedLines().size());
        for (String line : fileAppender.getCapturedLines()) {
            System.out.println(line);
        }
    }
}

