#include <stdexcept>
using namespace std;

enum class LogLevel { DEBUG = 0, INFO = 1, WARN = 2, ERROR = 3 };

string levelName(LogLevel level) {
    if (level == LogLevel::DEBUG) return "DEBUG";
    if (level == LogLevel::INFO) return "INFO";
    if (level == LogLevel::WARN) return "WARN";
    return "ERROR";
}

class LogRecord {
public:
    int sequenceNumber;
    string loggerName;
    LogLevel level;
    string message;

    LogRecord() : sequenceNumber(0), level(LogLevel::DEBUG) {}
    LogRecord(int seq, string logger, LogLevel lvl, string msg)
        : sequenceNumber(seq), loggerName(logger), level(lvl), message(msg) {}
};

class InvalidLoggerNameException : public runtime_error {
public: InvalidLoggerNameException(const string& msg) : runtime_error(msg) {}
};
class DuplicateAppenderException : public runtime_error {
public: DuplicateAppenderException(const string& msg) : runtime_error(msg) {}
};
class AppenderNotRegisteredException : public runtime_error {
public: AppenderNotRegisteredException(const string& msg) : runtime_error(msg) {}
};

class LogFormatter {
public:
    virtual string format(const LogRecord& record) = 0;
    virtual ~LogFormatter() {}
};

class PlainTextLogFormatter : public LogFormatter {
public:
    string format(const LogRecord& record) override {
        return "[" + levelName(record.level) + "] " + record.loggerName + ": " + record.message;
    }
};

class JsonLogFormatter : public LogFormatter {
public:
    string format(const LogRecord& record) override {
        return "{\"level\":\"" + levelName(record.level) + "\",\"logger\":\"" + record.loggerName + "\",\"message\":\"" + record.message + "\"}";
    }
};

class LogAppender {
public:
    virtual void onLog(const LogRecord& record) = 0;
    virtual ~LogAppender() {}
};

class ConsoleLogAppender : public LogAppender {
    LogLevel minLevel;
    shared_ptr<LogFormatter> formatter;

public:
    ConsoleLogAppender(LogLevel level, shared_ptr<LogFormatter> fmt) : minLevel(level), formatter(fmt) {}

    void onLog(const LogRecord& record) override {
        if ((int)record.level < (int)minLevel) return;
        cout << formatter->format(record) << endl;
    }
};

class FileLogAppender : public LogAppender {
    LogLevel minLevel;
    shared_ptr<LogFormatter> formatter;
    vector<string> capturedLines;

public:
    FileLogAppender(LogLevel level, shared_ptr<LogFormatter> fmt) : minLevel(level), formatter(fmt) {}

    void onLog(const LogRecord& record) override {
        if ((int)record.level < (int)minLevel) return;
        capturedLines.push_back(formatter->format(record));
    }

    vector<string> getCapturedLines() { return capturedLines; }
};

class Logger {
    string name;
    LogLevel minLevel;
    vector<shared_ptr<LogAppender>> appenders;
    int sequenceCounter = 0;

public:
    Logger() : minLevel(LogLevel::INFO) {}
    Logger(string n, LogLevel level) : name(n), minLevel(level) {}

    string getName() { return name; }

    void addAppender(shared_ptr<LogAppender> appender) {
        for (auto& existing : appenders) {
            if (existing == appender) throw DuplicateAppenderException("Appender is already registered on logger " + name);
        }
        appenders.push_back(appender);
    }

    void removeAppender(shared_ptr<LogAppender> appender) {
        auto it = find(appenders.begin(), appenders.end(), appender);
        if (it == appenders.end()) throw AppenderNotRegisteredException("Appender is not registered on logger " + name);
        appenders.erase(it);
    }

    void log(LogLevel level, string message) {
        if ((int)level < (int)minLevel) return;
        sequenceCounter++;
        LogRecord record(sequenceCounter, name, level, message);
        for (auto& appender : appenders) appender->onLog(record);
    }
};

class LoggerFactory {
    map<string, shared_ptr<Logger>> cache;

public:
    shared_ptr<Logger> getLogger(string name) {
        if (name.empty()) throw InvalidLoggerNameException("Logger name must not be blank");
        if (cache.find(name) != cache.end()) return cache.at(name);
        auto logger = make_shared<Logger>(name, LogLevel::INFO);
        cache[name] = logger;
        return logger;
    }
};

int main() {
    LoggerFactory factory;

    shared_ptr<Logger> logger1 = factory.getLogger("com.app.Service");
    shared_ptr<Logger> logger2 = factory.getLogger("com.app.Service");
    cout << "Same instance: " << (logger1 == logger2 ? "true" : "false") << endl;

    auto consoleAppender = make_shared<ConsoleLogAppender>(LogLevel::WARN, make_shared<PlainTextLogFormatter>());
    auto fileAppender = make_shared<FileLogAppender>(LogLevel::DEBUG, make_shared<JsonLogFormatter>());
    logger1->addAppender(consoleAppender);
    logger1->addAppender(fileAppender);

    logger1->log(LogLevel::DEBUG, "starting up");
    logger1->log(LogLevel::INFO, "service started");
    logger1->log(LogLevel::ERROR, "something failed");

    try {
        logger1->addAppender(consoleAppender);
    } catch (DuplicateAppenderException& e) {
        cout << "Caught expected: " << e.what() << endl;
    }

    shared_ptr<LogAppender> neverAdded = make_shared<ConsoleLogAppender>(LogLevel::ERROR, make_shared<PlainTextLogFormatter>());
    try {
        logger1->removeAppender(neverAdded);
    } catch (AppenderNotRegisteredException& e) {
        cout << "Caught expected: " << e.what() << endl;
    }

    try {
        factory.getLogger("");
    } catch (InvalidLoggerNameException& e) {
        cout << "Caught expected: " << e.what() << endl;
    }

    cout << "Captured file lines: " << fileAppender->getCapturedLines().size() << endl;
    for (auto& line : fileAppender->getCapturedLines()) {
        cout << line << endl;
    }

    return 0;
}
